from typing import Any, Dict, List, Union

def parse_json(s: str) -> Any:
    """
    Parses a JSON string without using the json module.

    Supports: null, true, false, numbers, strings, arrays, and objects.
    Raises ValueError on invalid input.

    Args:
        s: The JSON string to parse.

    Returns:
        The parsed Python object (None, bool, int, float, str, list, or dict).
    """
    def skip_whitespace(index: int) -> int:
        while index < len(s) and s[index] in ' \t\n\r':
            index += 1
        return index

    def parse_value(index: int) -> tuple[Any, int]:
        index = skip_whitespace(index)
        if index >= len(s):
            raise ValueError("Unexpected end of input")
        c = s[index]
        if c == '{':
            return parse_object(index)
        elif c == '[':
            return parse_array(index)
        elif c == '"':
            return parse_string(index)
        elif c == 't':
            return parse_true(index)
        elif c == 'f':
            return parse_false(index)
        elif c == 'n':
            return parse_null(index)
        else:
            return parse_number(index)

    def parse_object(index: int) -> tuple[Dict[str, Any], int]:
        index += 1  # skip '{'
        index = skip_whitespace(index)
        obj = {}
        if index < len(s) and s[index] == '}':
            return obj, index + 1
        while True:
            index = skip_whitespace(index)
            if index >= len(s) or s[index] != '"':
                raise ValueError("Expected string key in object")
            key, index = parse_string(index)
            index = skip_whitespace(index)
            if index >= len(s) or s[index] != ':':
                raise ValueError("Expected ':' after key in object")
            index += 1
            value, index = parse_value(index)
            obj[key] = value
            index = skip_whitespace(index)
            if index >= len(s):
                raise ValueError("Unterminated object")
            if s[index] == '}':
                return obj, index + 1
            elif s[index] != ',':
                raise ValueError("Expected ',' or '}' in object")
            index += 1

    def parse_array(index: int) -> tuple[List[Any], int]:
        index += 1  # skip '['
        index = skip_whitespace(index)
        arr = []
        if index < len(s) and s[index] == ']':
            return arr, index + 1
        while True:
            value, index = parse_value(index)
            arr.append(value)
            index = skip_whitespace(index)
            if index >= len(s):
                raise ValueError("Unterminated array")
            if s[index] == ']':
                return arr, index + 1
            elif s[index] != ',':
                raise ValueError("Expected ',' or ']' in array")
            index += 1

    def parse_string(index: int) -> tuple[str, int]:
        index += 1  # skip opening '"'
        result = []
        while index < len(s):
            c = s[index]
            if c == '"':
                return ''.join(result), index + 1
            elif c == '\\':
                index += 1
                if index >= len(s):
                    raise ValueError("Unterminated string escape")
                escaped = s[index]
                if escaped == '"':
                    result.append('"')
                elif escaped == '\\':
                    result.append('\\')
                elif escaped == '/':
                    result.append('/')
                elif escaped == 'b':
                    result.append('\b')
                elif escaped == 'f':
                    result.append('\f')
                elif escaped == 'n':
                    result.append('\n')
                elif escaped == 'r':
                    result.append('\r')
                elif escaped == 't':
                    result.append('\t')
                elif escaped == 'u':
                    if index + 4 >= len(s):
                        raise ValueError("Invalid unicode escape")
                    hex_str = s[index+1:index+5]
                    try:
                        code_point = int(hex_str, 16)
                    except ValueError:
                        raise ValueError("Invalid unicode escape")
                    result.append(chr(code_point))
                    index += 4
                else:
                    raise ValueError(f"Invalid escape character: {escaped}")
            else:
                result.append(c)
            index += 1
        raise ValueError("Unterminated string")

    def parse_true(index: int) -> tuple[bool, int]:
        if s[index:index+4] == 'true':
            return True, index + 4
        raise ValueError("Invalid true literal")

    def parse_false(index: int) -> tuple[bool, int]:
        if s[index:index+5] == 'false':
            return False, index + 5
        raise ValueError("Invalid false literal")

    def parse_null(index: int) -> tuple[None, int]:
        if s[index:index+4] == 'null':
            return None, index + 4
        raise ValueError("Invalid null literal")

    def parse_number(index: int) -> tuple[Union[int, float], int]:
        start = index
        if s[index] == '-':
            index += 1
        if index >= len(s):
            raise ValueError("Invalid number")
        if s[index] == '0':
            index += 1
            if index < len(s) and s[index].isdigit():
                raise ValueError("Leading zeros not allowed")
        elif s[index].isdigit():
            while index < len(s) and s[index].isdigit():
                index += 1
        else:
            raise ValueError("Invalid number")
        is_float = False
        if index < len(s) and s[index] == '.':
            is_float = True
            index += 1
            if index >= len(s) or not s[index].isdigit():
                raise ValueError("Invalid fractional part")
            while index < len(s) and s[index].isdigit():
                index += 1
        if index < len(s) and s[index] in 'eE':
            is_float = True
            index += 1
            if index < len(s) and s[index] in '+-':
                index += 1
            if index >= len(s) or not s[index].isdigit():
                raise ValueError("Invalid exponent")
            while index < len(s) and s[index].isdigit():
                index += 1
        num_str = s[start:index]
        try:
            if is_float:
                return float(num_str), index
            else:
                return int(num_str), index
        except ValueError:
            raise ValueError("Invalid number")

    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    s = s.strip()
    if not s:
        raise ValueError("Empty input")
    result, index = parse_value(0)
    index = skip_whitespace(index)
    if index != len(s):
        raise ValueError("Extra data after JSON value")
    return result

