/**
 * Waits for all promises to be resolved, or rejects with the first rejection.
 * Behaves identically to the native Promise.all.
 *
 * @typeParam T - The type of the resolved value of the promises.
 * @param promises - An array of Promises to wait for.
 * @returns A new Promise that resolves to an array of resolved values in the same order as the input, 
 *          or rejects with the reason of the first rejected promise.
 */
function promiseAll<T>(promises: Promise<T>[]): Promise<T[]> {
  return new Promise<T[]>((resolve, reject) => {
    const results: T[] = [];
    let completedCount = 0;

    if (promises.length === 0) {
      resolve(results);
      return;
    }

    promises.forEach((promise, index) => {
      promise.then(
        (value) => {
          results[index] = value;
          completedCount++;
          if (completedCount === promises.length) {
            resolve(results);
          }
        },
        (reason) => {
          reject(reason);
        }
      );
    });
  });
}

