/// Parses a vector of strings into a vector of 32-bit integers.
///
/// # Arguments
///
/// * `lines` - A vector of strings, where each string represents a number.
///
/// # Returns
///
/// * `Ok(Vec<i32>)` if all lines are successfully parsed.
/// * `Err(String)` containing the first invalid line if parsing fails.
pub fn parse_numbers(lines_lines: Vec<String>) -> Result<Vec<i32>, String> {
    let mut numbers = Vec::with_capacity(number_lines.len());
    for line in number_lines {
        let num: i32 = line.trim().parse().map_err(|_| line)?;
        numbers.push(num);
    }
    Ok(numbers)
}
